local item_lib = require("items")
local function staging(e)
 return e.qglobals.coldainWarPhase=="staging" and e.qglobals.coldainWarStaging=="active"
end

function event_say(e) require("coldain_ring_war").scout_order(e) end
function event_trade(e)
 if e.self:GetNPCTypeID()==2000966 and staging(e) and item_lib.check_turn_in(e.trade,{item1=18511}) then
  eq.set_global("coldainWarPhase","preparing",3,"F")
  eq.del_global("coldainWarStaging")
  eq.follow(e.other:GetID())
  eq.signal(2000968,2)
  e.self:Say("At yer service, "..e.other:GetCleanName()..". Remember now, before issuing me an order ya must disengage from any combat and be sure yer speakin to me. I advise you to avoid combat at all costs, your leadership is crucial.")
 end
 item_lib.return_items(e.self,e.other,e.trade)
end
